from __future__ import annotations

from typing import Any

from orders.application.errors import Conflict, OrderNotFound, ProductNotFound
from orders.application.fulfilment_service import FulfilmentService
from orders.controllers.http import (InvalidRequest, Response, bad_request, conflict, not_found,
                                     require_non_negative_int, require_positive_int, require_str)


class FulfilmentController:
    def __init__(self, service: FulfilmentService) -> None:
        self._service = service

    def handle_packing_slip(self, order_id: str) -> Response:
        try:
            slip = self._service.packing_slip(order_id)
        except OrderNotFound:
            return not_found("order")
        except Conflict as exc:
            return conflict(exc)
        return Response(200, {
            "order_id": slip.order_id,
            "customer_name": slip.customer_name,
            "lines": [{"sku": line.sku, "name": line.name, "quantity": line.quantity}
                      for line in slip.lines],
        })

    def handle_low_stock(self, threshold: int) -> Response:
        try:
            threshold = require_non_negative_int(threshold, "threshold")
        except InvalidRequest as exc:
            return bad_request(exc)
        products = self._service.low_stock(threshold)
        return Response(200, {"products": [{"sku": p.sku, "name": p.name, "on_hand": p.on_hand}
                                           for p in products]})

def _order(shop):
    return shop.orders.handle_create(
        {"customer_id": "c1", "items": [{"sku": "PEN", "quantity": 3}, {"sku": "BOOK", "quantity": 1}]}
    ).body["order_id"]


def test_packing_slip(shop):
    oid = _order(shop)
    r = shop.fulfilment.handle_packing_slip(oid)
    assert r.status == 200
    assert r.body == {"order_id": oid, "customer_name": "Ada", "lines": [
        {"sku": "PEN", "name": "Pen", "quantity": 3}, {"sku": "BOOK", "name": "Book", "quantity": 1}]}


def test_unknown_order(shop):
    r = shop.fulfilment.handle_packing_slip("nope")
    assert (r.status, r.body) == (404, {"error": "order not found"})


def test_cancelled_order(shop):
    oid = _order(shop)
    shop.orders.handle_cancel(oid)
    r = shop.fulfilment.handle_packing_slip(oid)
    assert r.status == 409 and "error" in r.body


def test_low_stock_sorted_and_strict(shop):
    shop.catalog.handle_add_product({"sku": "AAA", "name": "Aaa", "unit_price_cents": 1, "on_hand": 5})
    r = shop.fulfilment.handle_low_stock(51)
    assert r.status == 200
    assert r.body == {"products": [
        {"sku": "AAA", "name": "Aaa", "on_hand": 5}, {"sku": "LAMP", "name": "Lamp", "on_hand": 5},
        {"sku": "BOOK", "name": "Book", "on_hand": 50}]}
    assert shop.fulfilment.handle_low_stock(5).body == {"products": []}


def test_low_stock_excludes_inactive():
    from orders.application.fulfilment_service import FulfilmentService
    from orders.controllers.fulfilment import FulfilmentController
    from orders.domain.catalog import Product
    from orders.infrastructure.catalog import InMemoryProductCatalog
    from orders.infrastructure.customers import InMemoryCustomerRepository
    from orders.infrastructure.repository import InMemoryOrderRepository
    from orders.infrastructure.stock import InMemoryStockRepository

    catalog, stock = InMemoryProductCatalog(), InMemoryStockRepository()
    catalog.add(Product("OLD", "Old", 100, active=False))
    catalog.add(Product("NEW", "New", 100))
    controller = FulfilmentController(FulfilmentService(
        InMemoryOrderRepository(), InMemoryCustomerRepository(), catalog, stock))
    assert controller.handle_low_stock(10).body == {"products": [{"sku": "NEW", "name": "New", "on_hand": 0}]}


def test_low_stock_invalid_threshold(shop):
    for bad in (-1, True, "3", 1.5, None):
        r = shop.fulfilment.handle_low_stock(bad)
        assert r.status == 400 and "error" in r.body

